  "inlineSchema": "// Prisma schema for Weekly Vocabulary App (PostgreSQL/Supabase)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/client\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\") // Required for Supabase\n}\n\n// User management\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  name      String?\n  password  String?\n  image     String?\n  role      String   @default(\"STUDENT\") // STUDENT, TEACHER, ADMIN\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  studentProgress StudentProgress[]\n  teacherClasses  Class[]           @relation(\"ClassTeacher\")\n  accounts        Account[]\n  sessions        Session[]\n  enrollments     Enrollment[]\n  quizSessions    QuizSession[]\n  importBatches   ImportBatch[]     @relation(\"ImportBatchTeacher\")\n\n  @@index([email])\n}\n\n// NextAuth models\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@index([userId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// Student progress tracking\nmodel StudentProgress {\n  id         String @id @default(cuid())\n  userId     String\n  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  grade      String // G1, G2, G3, G4, G5\n  subject    String\n  difficulty String @default(\"EASY\") // EASY, MEDIUM, HARD\n\n  // Overall progress\n  totalScore        Int    @default(0)\n  overallProgress   Float  @default(0)\n  currentPlantStage String @default(\"SEEDLING\") // SEEDLING, SAPLING, YOUNG_TREE, MIGHTY_OAK\n\n  // Relations\n  weekProgress WeekProgress[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, grade, subject], name: \"userId_grade_subject\")\n  @@index([userId, grade])\n}\n\nmodel WeekProgress {\n  id                String          @id @default(cuid())\n  studentProgressId String\n  studentProgress   StudentProgress @relation(fields: [studentProgressId], references: [id], onDelete: Cascade)\n\n  weekId    Int\n  completed Boolean @default(false)\n  locked    Boolean @default(true)\n  score     Int     @default(0)\n\n  // Quiz stats\n  questionsCorrect Int @default(0)\n  questionsTotal   Int @default(0)\n\n  // Reading comprehension stats\n  readingCompCorrect Int @default(0)\n  readingCompTotal   Int @default(0)\n\n  // Mastered keywords (stored as JSON string array)\n  keywordsMastered String // JSON array: [\"keyword1\", \"keyword2\"]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([studentProgressId, weekId])\n  @@index([studentProgressId, weekId])\n}\n\n// Class management (for teacher portal)\nmodel Class {\n  id        String @id @default(cuid())\n  name      String\n  teacherId String\n  teacher   User   @relation(\"ClassTeacher\", fields: [teacherId], references: [id])\n  grade     String // G1, G2, G3, G4, G5\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  enrollments   Enrollment[]\n  importBatches ImportBatch[]\n\n  @@index([teacherId])\n}\n\nmodel Enrollment {\n  id        String @id @default(cuid())\n  classId   String\n  class     Class  @relation(fields: [classId], references: [id], onDelete: Cascade)\n  studentId String\n  student   User   @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  enrolledAt    DateTime @default(now())\n  parentEmail   String? // Parent contact email\n  parentPhone   String? // Parent contact phone\n  importBatchId String? // Track which import batch added this student\n  comments      String? // Teacher notes\n\n  importBatch ImportBatch? @relation(fields: [importBatchId], references: [id])\n\n  @@unique([classId, studentId])\n  @@index([studentId])\n}\n\n// Session tracking for active quiz state\nmodel QuizSession {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  grade      String // G1, G2, G3, G4, G5\n  subject    String\n  weekId     Int\n  difficulty String // EASY, MEDIUM, HARD\n\n  // Current quiz state\n  currentQuestionIndex Int     @default(0)\n  selectedAnswer       String?\n  isAnswered           Boolean @default(false)\n  isCorrect            Boolean @default(false)\n  timeRemaining        Int     @default(0)\n  livesRemaining       Int     @default(0)\n\n  // Temporary scores\n  scoreThisQuestion Int @default(0)\n  correctCount      Int @default(0)\n  speedBonusCount   Int @default(0)\n\n  // Quiz answers history (JSON)\n  answersHistory String // JSON array of answer records\n\n  status      String    @default(\"IN_PROGRESS\") // IN_PROGRESS, COMPLETED, ABANDONED\n  startedAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@index([userId, status])\n}\n\n// Bulk student import tracking\nmodel ImportBatch {\n  id           String   @id @default(cuid())\n  teacherId    String\n  teacher      User     @relation(\"ImportBatchTeacher\", fields: [teacherId], references: [id])\n  classId      String\n  class        Class    @relation(fields: [classId], references: [id])\n  fileName     String // Original filename\n  recordsCount Int // Total records in file\n  successCount Int // Successfully imported\n  failureCount Int // Failed records\n  errorLog     String? // JSON array: [{row, email, error}]\n  createdAt    DateTime @default(now())\n\n  enrollments Enrollment[]\n\n  @@index([teacherId, createdAt])\n}\n",
